import type { Meta, StoryObj } from '@storybook/react-webpack5';
import React from 'react';
import { expect, within } from 'storybook/test';
import { Box, SimpleGrid, Text } from '@chakra-ui/react';
import { ZimmLogo } from '.';

const meta: Meta<typeof ZimmLogo> = {
  title: 'Elements/ZimmLogo',
  component: ZimmLogo,
};
export default meta;

type Story = StoryObj<typeof ZimmLogo>;

export const Default: Story = {
  args: {
    variant: 'default',
  },
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);
    const logo = canvas.getByRole('img', { name: 'Zimmermann' });
    await expect(logo).toBeInTheDocument();
  },
};

export const Inverse: Story = {
  args: {
    variant: 'inverse',
  },
  decorators: [
    (Story) => (
      <Box bg="background.05" p={6} display="inline-flex">
        <Story />
      </Box>
    ),
  ],
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);
    const logo = canvas.getByRole('img', { name: 'Zimmermann' });
    await expect(logo).toBeInTheDocument();
  },
};

export const BothVariants: Story = {
  render: () => (
    <SimpleGrid columns={1} gap={6}>
      <Box>
        <Text textStyle="caption" color="text.secondary" mb={2}>
          Default (dark on light)
        </Text>
        <Box bg="background.07" p={4} borderWidth="default" borderStyle="solid" borderColor="border.default">
          <ZimmLogo variant="default" />
        </Box>
      </Box>
      <Box>
        <Text textStyle="caption" color="text.secondary" mb={2}>
          Inverse (light on dark)
        </Text>
        <Box bg="background.05" p={4}>
          <ZimmLogo variant="inverse" />
        </Box>
      </Box>
    </SimpleGrid>
  ),
};

export const CustomWidth: Story = {
  render: () => (
    <Box p={6} display="flex" flexDirection="column" gap={6}>
      {([160, 240, 320] as const).map((w) => (
        <Box key={w}>
          <Text textStyle="caption" color="text.secondary" mb={1}>
            {w}px
          </Text>
          <ZimmLogo style={{ maxWidth: `${w}px` }} />
        </Box>
      ))}
    </Box>
  ),
};

