          <ZimmIcon type="search" size={size} aria-hidden={true} />
          <Text textStyle="caption">{iconSizes[size]}</Text>
        </VStack>
      ))}
    </Box>
  ),
};

export const Decorative: Story = {
  args: {
    type: 'close',
    size: 'md',
    'aria-hidden': true,
  },
