cat > /tmp/s2probe/paths.mjs <<'EOF'
import pw from '/Users/marcel.a.n.navarro/Dev/zimmermann-pwa/node_modules/playwright-core/index.js';
const { chromium } = pw;
const browser = await chromium.launch();
const out = {};
for (const [name, viewport] of [['desktop1440',{width:1440,height:900}],['mobile390',{width:390,height:844}]]) {
  const ctx = await browser.newContext({ viewport });
  const page = await ctx.newPage();
  await page.goto('http://localhost:3000/', { waitUntil: 'load', timeout: 90000 });
  await page.locator('footer svg[aria-label="Zimmermann"]').first().waitFor({ timeout: 60000 });
  await page.waitForTimeout(2000);
  out[name] = await page.evaluate(() => {
    const svg = document.querySelector('footer svg[aria-label="Zimmermann"]');
    const paths = [...svg.querySelectorAll('path')];
    return {
      count: paths.length,
      allAttrWhite: paths.every(p => p.getAttribute('fill') === '#ffffff'),
      allComputedWhite: paths.every(p => getComputedStyle(p).fill === 'rgb(255, 255, 255)'),
      distinctAttr: [...new Set(paths.map(p => p.getAttribute('fill')))],
      distinctComputed: [...new Set(paths.map(p => getComputedStyle(p).fill))],
      // every path must actually paint (non-zero ink box)
      allPainted: paths.every(p => { const b = p.getBBox(); return b.width > 0 && b.height > 0; }),
    };
  });
  await ctx.close();
}
await browser.close();
console.log(JSON.stringify(out, null, 2));
EOF
